    void download(size_t index){auto p=presets.at(index);if(!connected()){message(tr("download"),tr("noNetwork"));return;}auto url=wide(p.get("Url").str());validateUrl(url);if(!confirm(tr("download"),tr("downloadConfirm")+L" "+presetName(p)+L"?\r\n"+url))return;auto browser=edge();if(browser.empty()){if(!confirm(tr("download"),tr("edgeMissing")))return;shell(url);}else shell(browser,quote(url));std::wstring locations;for(auto& dir:downloadFolders())locations+=dir.wstring()+L"\r\n";message(presetName(p),tr("edgeStarted")+L"\r\n\r\n"+tr("downloadLocations")+L"\r\n"+locations+L"\r\n"+tr("edgeInstallHint"));}
